  mem.bias = 0; mem.hd = obs.heading || 0; mem.ref = null;
  mem.hist = [];
  mem.skip = [];
  mem.mode = 'explore'; mem.dockT = 0; mem.noDelUntil = -1;
  mem.cur = null;
  mem.drilling = false; mem.dT0 = 0; mem.dX = 0; mem.dY = 0; mem.dSite = null; mem.holdI = 0;
  mem.lastSiteT = -100; mem.siteT0 = 0;
  mem.backT = 0; mem.backTurn = 0; mem.flip = 1;
  mem.avT = 0; mem.avDir = 1;
  mem.lastL = 0; mem.lastR = 0; mem.lastAvg = 0;
  mem.rLast = []; mem.rCnt = [];
  mem.ticks = 0; mem.bumpN = 0; mem.sampledN = 0;
  mem.frozen = 0; mem.lastGx = NaN; mem.lastGy = NaN; mem.gpsFrozen = false;
}

function addGrid(mem) {
  mem.gridAdded = true;
  for (const gx of [60, 200, 340]) for (const gy of [60, 200, 340]) {
    mem.hints.push({ x: gx, y: gy, est: 0.3, done: false, bad: 0, arrived: false, t0: 0, wps: [], wi: 0, sT: 0 });
