// heading = compass + bias; bias learned from GPS displacement on straight commanded runs
function updateHeading(obs, mem) {
  const straight = mem.lastL > 0.2 && mem.lastR > 0.2 &&
    Math.abs(mem.lastL - mem.lastR) < 0.2 && !mem.gpsFrozen && !obs.bumped;
  if (straight) {
    if (!mem.ref) mem.ref = { x: obs.x, y: obs.y };
    else if (dist(mem.ref.x, mem.ref.y, obs.x, obs.y) >= 8) {
