  }
  let spd = v * (1 - ae / 60);
  if (spd < MINF) spd = MINF;
  const steer = clamp(0.012 * err, -0.25, 0.25);
  return mk(spd - steer, spd + steer);
}

function driveTo(err, v, d) {
  const front = Math.min(d[3], d[4], d[5]);
  const f = front < 6 ? clamp((front - 2) / 4, 0.4, 1) : 1;
  return drive(err, v * f);
}

function navTo(obs, mem, tx, ty, v, d, stopR) {
  const dx = tx - obs.x, dy = ty - obs.y;
  const dd = Math.hypot(dx, dy);
  if (dd <= stopR) return null;
  const err = wrap(Math.atan2(dy, dx) * R2D - mem.hd);
  return driveTo(err, clamp(0.1 + 0.1 * dd, 0.2, v), d);
}

function startBack(mem) {
  mem.backT = 12;
  mem.flip = -mem.flip;
  mem.backTurn = mem.flip * 0.2;
}

function siteWorld(obs, mem, s) {
  const a = (mem.hd + s.bearing) * D2R;
  return { x: obs.x + s.distance * Math.cos(a), y: obs.y + s.distance * Math.sin(a) };
}

function siteStep(obs, mem, d, s) {
  const sp = (Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0)) / 2;
  if (s.distance <= 1.3) {
    if (sp < 0.1) {
      const sw = siteWorld(obs, mem, s);
      mem.drilling = true; mem.dT0 = mem.ticks;
      mem.dX = obs.x; mem.dY = obs.y; mem.dSite = sw; mem.holdI = 0;
      return { left: 0, right: 0, drill: true };
    }
    return zero();
  }
  const v = clamp(0.1 + 0.12 * s.distance, 0.2, 0.3);
  return driveTo(s.bearing, v, d);
}

function drillStep(obs, mem) {
  const el = obs.drilling || 0;
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  const moved = dist(obs.x, obs.y, mem.dX, mem.dY);
  if (el >= 6.3) {
    mem.drilling = false; mem.holdI = 0;
    const s = mem.dSite;
    addSkip(mem, s.x, s.y, 1);
    for (const h of mem.hints) {
      if (h !== mem.cur && dist(h.x, h.y, s.x, s.y) < 15) h.done = true;
    }
    mem.sampledN++;
    return zero();
  }
  if (moved > 3.0 || mem.ticks - mem.dT0 > 200) {
    mem.drilling = false; mem.holdI = 0;
    addSkip(mem, mem.dSite.x, mem.dSite.y, 2);
    return zero();
  }
  mem.holdI = clamp(mem.holdI - 0.05 * avg, -0.4, 0.4);
  const c = clamp(mem.holdI - 1.5 * avg, -0.4, 0.4);
  return { left: c, right: c, drill: true };
}

function pushScience(obs, mem) {
  if (!(obs.science > 0.6) || mem.pushed >= 6 || obs.site) return;
  for (const h of mem.hints) if (!h.done && dist(h.x, h.y, obs.x, obs.y) < 10) return;
  for (const p of mem.skip) if (dist(p.x, p.y, obs.x, obs.y) < 10) return;
  mem.hints.push({ x: obs.x, y: obs.y, est: obs.science * 4, done: false, bad: 0, arrived: false, t0: 0, wps: [], wi: 0, sT: 0 });
  mem.pushed++;
}

function pickTarget(obs, mem) {
  for (let pass = 0; pass < 3; pass++) {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done) continue;
      const d = dist(obs.x, obs.y, h.x, h.y);
      const s = h.est / (d + 60);
      if (s > bs) { bs = s; best = h; }
    }
    if (best) {
      best.arrived = false; best.bad = 0; best.t0 = mem.ticks;
      mem.cur = best;
      return;
    }
    if (!mem.gridAdded) { addGrid(mem); continue; }
    if (mem.cycles >= 1) break;
    for (const h of mem.hints) { h.done = false; h.bad = 0; }
    mem.cycles++;
  }
  mem.cur = null;
}

// square loop of half-side 6 m around the hint; detection radius 8 m covers about 14 m around it
function lawnPts(obs, c) {
  const offs = [[-6, -6], [6, -6], [6, 6], [-6, 6]];
  const pts = offs.map(p => ({ x: clamp(c.x + p[0], 3, 397), y: clamp(c.y + p[1], 3, 397) }));
  let k = 0, best = 1e9;
  for (let i = 0; i < 4; i++) {
    const dd = dist(obs.x, obs.y, pts[i].x, pts[i].y);
    if (dd < best) { best = dd; k = i; }
  }
  return [pts[k], pts[(k + 1) % 4], pts[(k + 2) % 4], pts[(k + 3) % 4], pts[k]];
}

function markNear(mem, x, y, r) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < r) h.done = true;
}

function decide(obs, mem, d) {
  const carried = obs.carried || 0;
  const dB = dist(obs.x, obs.y, mem.base.x, mem.base.y);
  const fwd = mem.lastAvg > 0.15;

  if (obs.bumped) {
    mem.bumpN++;
    startBack(mem);
    if (mem.cur) mem.cur.bad += 1;
  }
  if (!mem.gpsFrozen && mem.backT <= 0 && mem.avT <= 0 && fwd && mem.hist.length >= 31) {
    const p = mem.hist[mem.hist.length - 31];
    if (dist(obs.x, obs.y, p.x, p.y) < 0.5) {
      startBack(mem);
      if (mem.cur) mem.cur.bad += 0.5;
    }
  }
  if (mem.backT > 0) {
    mem.backT--;
    return mk(-0.3 + mem.backTurn, -0.3 - mem.backTurn);
  }
  if (mem.avT > 0) {
    mem.avT--;
    return mk(-0.25 * mem.avDir, 0.25 * mem.avDir);
  }
  const front = Math.min(d[3], d[4], d[5]);
  if (fwd && front < 2.5 && dB > 4) {
    const L = Math.min(d[5], d[6], d[7], d[8]);
    const R = Math.min(d[0], d[1], d[2], d[3]);
    mem.avDir = L >= R ? 1 : -1;
    mem.avT = 6;
    return mk(-0.25 * mem.avDir, 0.25 * mem.avDir);
  }

  // delivery triggers
  if (mem.mode === 'explore' && carried > 0) {
    const eta = dB / 0.4 + 60;
    const urgent = carried >= mem.cap || obs.timeLeft < eta || obs.battery < 0.25;
    const opportunistic = obs.t >= mem.noDelUntil &&
      ((carried >= 3 && dB < 60) || (carried >= 2 && dB < 30) || (carried >= 1 && dB < 15));
    if (urgent || opportunistic) { mem.mode = 'deliver'; mem.dockT = 0; }
  }

  if (mem.mode === 'deliver') {
    if (carried === 0) { mem.mode = 'explore'; return zero(); }
    const b = obs.beacon;
    const haveB = !!(b && b.distance <= 20);
    const dd = haveB ? b.distance : dB;
    if (dd <= 2.4) {
      mem.dockT++;
      if (mem.dockT > 60) { mem.mode = 'explore'; mem.dockT = 0; mem.noDelUntil = obs.t + 60; }
      return zero();
    }
    mem.dockT = 0;
    if (haveB) return driveTo(b.bearing, clamp(0.1 + 0.1 * dd, 0.2, CRUISE), d);
    return navTo(obs, mem, mem.base.x, mem.base.y, CRUISE, d, 2.0) || zero();
  }

  // sites within 8 m: approach and drill
  if (obs.site && carried < mem.cap) {
    if (obs.t - mem.lastSiteT > 1.0) mem.siteT0 = obs.t;
    mem.lastSiteT = obs.t;
    const sw = siteWorld(obs, mem, obs.site);
    if (!findSkip(mem, sw.x, sw.y)) {
      if (obs.t - mem.siteT0 > 60) {
        addSkip(mem, sw.x, sw.y, 2);
      } else {
        return siteStep(obs, mem, d, obs.site);
      }
    }
  }

  pushScience(obs, mem);
  if (!mem.cur || mem.cur.done) pickTarget(obs, mem);
  const cur = mem.cur;
  if (!cur) return zero();

  if (cur.bad >= 3 || mem.ticks - cur.t0 > 1500) {
    cur.done = true; mem.cur = null;
    return zero();
  }
  if (!cur.arrived) {
    if (dist(obs.x, obs.y, cur.x, cur.y) < 4) {
      cur.arrived = true;
      cur.wps = lawnPts(obs, cur);
      cur.wi = 0;
      cur.sT = mem.ticks;
    } else {
      return navTo(obs, mem, cur.x, cur.y, CRUISE, d, 3.0) || zero();
    }
  }
  if (cur.wi >= cur.wps.length || mem.ticks - cur.sT > 800) {
    cur.done = true;
    markNear(mem, cur.x, cur.y, 10);
    mem.cur = null;
    return zero();
  }
  const w = cur.wps[cur.wi];
  if (dist(obs.x, obs.y, w.x, w.y) < 1.5) { cur.wi++; return zero(); }
  return navTo(obs, mem, w.x, w.y, CRUISE, d, 1.0) || zero();
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.ticks++;
  mem.hist.push({ x: obs.x, y: obs.y });
  if (mem.hist.length > 40) mem.hist.shift();
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.frozen++;
  else { mem.frozen = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  mem.gpsFrozen = mem.frozen > 30 && mem.lastAvg > 0.15;

  updateHeading(obs, mem);
  const d = readRays(obs, mem);
  const cmd = mem.drilling ? drillStep(obs, mem) : decide(obs, mem, d);
  mem.lastL = cmd.left; mem.lastR = cmd.right;
  mem.lastAvg = (cmd.left + cmd.right) / 2;
  return { left: cmd.left, right: cmd.right, drill: !!cmd.drill };
}

function act(obs, mem) {
  try {
    return step(obs, mem);
  } catch (e) {
    return zero();
  }
}

const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;
const CRUISE = 0.45;
const MINF = 0.2;
const KS = 0.008;

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(bx - ax, by - ay); }
function zero() { return { left: 0, right: 0, drill: false }; }
function mk(l, r) { return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: false }; }

function newHint(x, y, est) {
  return { x: x, y: y, est: est, done: false, bad: 0, arrived: false, t0: 0, wps: [], wi: 0, sT: 0 };
}

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.base = m.base || { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map(h =>
    newHint(h.x, h.y, typeof h.estimate === 'number' ? Math.max(h.estimate, 0.05) : 1));
  mem.gridAdded = false; mem.cycles = 0; mem.pushed = 0;
  mem.bias = 0; mem.ref = null; mem.hd = obs.heading || 0;
  mem.skip = [];
  mem.mode = 'explore'; mem.purpose = ''; mem.dockT = 0; mem.noDelUntil = -1;
  mem.cur = null;
  mem.drilling = false; mem.dT0 = 0; mem.dX = 0; mem.dY = 0; mem.dSite = null; mem.holdI = 0;
  mem.lastSiteT = -100; mem.siteT0 = 0;
  mem.backT = 0; mem.avT = 0; mem.avDir = 1;
  mem.lastL = 0; mem.lastR = 0; mem.lastAvg = 0;
  mem.rLast = []; mem.rCnt = [];
  mem.ticks = 0; mem.bumpN = 0; mem.sampledN = 0; mem.escN = 0;
  mem.frozen = 0; mem.lastGx = NaN; mem.lastGy = NaN; mem.gpsFrozen = false;
  mem.px = obs.x; mem.py = obs.y;
  mem.pos = [];
}

function addGrid(mem) {
  mem.gridAdded = true;
  for (const gx of [60, 200, 340]) for (const gy of [60, 200, 340]) {
    mem.hints.push(newHint(gx, gy, 0.3));
  }
}

function findSkip(mem, x, y) {
  for (const s of mem.skip) if (dist(s.x, s.y, x, y) < 4) return s;
  return null;
}
function addSkip(mem, x, y, inc) {
  const s = findSkip(mem, x, y);
  if (s) s.n += inc; else mem.skip.push({ x: x, y: y, n: inc });
}
function markNear(mem, x, y, r) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < r) h.done = true;
}

// heading = compass + bias; bias learned from GPS track on straight forward runs
function updateHeading(o, mem) {
  const straight = mem.lastL > 0.2 && mem.lastR > 0.2 &&
    Math.abs(mem.lastL - mem.lastR) < 0.15 && !mem.gpsFrozen &&
    mem.backT <= 0 && mem.avT <= 0;
  if (straight) {
    if (!mem.ref) mem.ref = { x: o.x, y: o.y };
    else if (dist(mem.ref.x, mem.ref.y, o.x, o.y) >= 8) {
      const g = Math.atan2(o.y - mem.ref.y, o.x - mem.ref.x) * R2D;
      const e = wrap(g - wrap((o.heading || 0) + mem.bias));
      mem.bias = wrap(mem.bias + 0.15 * e);
      mem.ref = { x: o.x, y: o.y };
    }
  } else mem.ref = null;
  mem.hd = wrap((o.heading || 0) + mem.bias);
}

function readRays(obs, mem) {
  const r = obs.rays || [];
  const moving = mem.lastAvg > 0.15;
  const d = [];
  for (let i = 0; i < 9; i++) {
    let v = Number(r[i]);
    if (!(v > 0)) v = 15;
    if (v > 15) v = 15;
    if (moving) {
      if (mem.rLast[i] === v) mem.rCnt[i] = (mem.rCnt[i] || 0) + 1;
      else { mem.rCnt[i] = 0; mem.rLast[i] = v; }
    }
    if ((mem.rCnt[i] || 0) > 80) v = 15; // sensor looks stuck
    d.push(v);
  }
  return d;
}

// err in degrees, positive = target to the left
function steerCmd(err, v) {
  const ae = Math.abs(err);
  if (ae > 60) {
    const s = err > 0 ? 1 : -1;
    return mk(-0.3 * s, 0.3 * s);
  }
  let spd = v * (1 - ae / 90);
  if (spd < MINF) spd = MINF;
  const st = clamp(KS * err, -0.3, 0.3);
  return mk(spd - st, spd + st);
}

function slowF(d) {
  const f = Math.min(d[3], d[4], d[5]);
  return f < 5 ? clamp((f - 1.5) / 3.5, 0.35, 1) : 1;
}

function navTo(o, mem, tx, ty, v, d, stopR) {
  const dd = dist(o.x, o.y, tx, ty);
  if (dd <= stopR) return null;
  const err = wrap(Math.atan2(ty - o.y, tx - o.x) * R2D - mem.hd);
  return steerCmd(err, clamp(0.15 + 0.15 * dd, 0.2, v) * slowF(d));
}

function openSide(d) {
  const L = Math.min(d[5], d[6], d[7], d[8]);
  const R = Math.min(d[0], d[1], d[2], d[3]);
  return L >= R ? 1 : -1;
}

function startBack(mem, d) {
  mem.avDir = openSide(d);
  mem.backT = 15;
}

function siteWorld(o, mem, s) {
  const a = (mem.hd + s.bearing) * D2R;
  return { x: o.x + s.distance * Math.cos(a), y: o.y + s.distance * Math.sin(a) };
}

function drillStep(o, obs, mem) {
  const el = obs.drilling || 0;
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  const moved = dist(o.x, o.y, mem.dX, mem.dY);
  if (el >= 6.3) {
    mem.drilling = false; mem.holdI = 0;
    const s = mem.dSite;
    addSkip(mem, s.x, s.y, 1);
    for (const h of mem.hints) {
      if (h !== mem.cur && dist(h.x, h.y, s.x, s.y) < 15) h.done = true;
    }
    mem.sampledN++;
    return zero();
  }
  if (moved > 3.0 || mem.ticks - mem.dT0 > 200) {
    mem.drilling = false; mem.holdI = 0;
    addSkip(mem, mem.dSite.x, mem.dSite.y, 2);
    return zero();
  }
  mem.holdI = clamp(mem.holdI - 0.05 * avg, -0.4, 0.4);
  const c = clamp(mem.holdI - 1.5 * avg, -0.4, 0.4);
  return { left: c, right: c, drill: true };
}

function siteStep(o, obs, mem, d, s, sw) {
  const sp = (Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0)) / 2;
  if (s.distance <= 1.3) {
    if (sp < 0.12) {
      mem.drilling = true; mem.dT0 = mem.ticks;
      mem.dX = o.x; mem.dY = o.y; mem.dSite = sw; mem.holdI = 0;
      mem.pos = [];
      return { left: 0, right: 0, drill: true };
    }
    return zero();
  }
  return steerCmd(s.bearing, clamp(0.15 + 0.12 * s.distance, 0.2, 0.35) * slowF(d));
}

function pushScience(o, obs, mem) {
  if (!(obs.science > 1.0) || mem.pushed >= 6 || obs.site) return;
  for (const h of mem.hints) if (!h.done && dist(h.x, h.y, o.x, o.y) < 10) return;
  for (const p of mem.skip) if (dist(p.x, p.y, o.x, o.y) < 10) return;
  mem.hints.push(newHint(o.x, o.y, Math.max(0.1, obs.science * 3)));
  mem.pushed++;
}

function pickTarget(o, mem) {
  for (let pass = 0; pass < 3; pass++) {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done) continue;
      const d = dist(o.x, o.y, h.x, h.y);
      const s = h.est / (d + 50);
      if (s > bs) { bs = s; best = h; }
    }
    if (best) {
      best.arrived = false; best.bad = 0; best.t0 = mem.ticks;
      best.wps = []; best.wi = 0;
      mem.cur = best;
      return;
    }
    if (!mem.gridAdded) { addGrid(mem); continue; }
    if (mem.cycles >= 1) break;
    for (const h of mem.hints) { h.done = false; h.bad = 0; }
    mem.cycles++;
  }
  mem.cur = null;
}

// rectangle around the hint (half sides 9 x 6), starting at the nearest corner
function lawnPts(o, c) {
  const offs = [[-9, -6], [9, -6], [9, 6], [-9, 6]];
  const pts = offs.map(p => ({ x: clamp(c.x + p[0], 3, 397), y: clamp(c.y + p[1], 3, 397) }));
  let k = 0, best = 1e9;
  for (let i = 0; i < 4; i++) {
    const dd = dist(o.x, o.y, pts[i].x, pts[i].y);
    if (dd < best) { best = dd; k = i; }
  }
  return [pts[k], pts[(k + 1) % 4], pts[(k + 2) % 4], pts[(k + 3) % 4]];
}

function deliverStep(o, obs, mem, d) {
  const b = obs.beacon;
  const haveB = !!(b && b.distance <= 20);
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);
  const dd = haveB ? b.distance : dB;
  if (dd <= 2.4) {
    mem.pos = [];
    mem.dockT++;
    if (mem.dockT > 60 && mem.purpose === 'deliver') {
      mem.mode = 'explore'; mem.dockT = 0; mem.noDelUntil = (obs.t || 0) + 60;
    }
    return zero();
  }
  mem.dockT = 0;
  if (haveB) return steerCmd(b.bearing, clamp(0.15 + 0.12 * dd, 0.2, CRUISE) * slowF(d));
  return navTo(o, mem, mem.base.x, mem.base.y, CRUISE, d, 2.0) || zero();
}

function decide(o, obs, mem, d) {
  const carried = obs.carried || 0;
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);
  const fwd = mem.lastAvg > 0.15;

  if (mem.drilling) { mem.pos = []; return drillStep(o, obs, mem); }

  // bump recovery
  if (obs.bumped) {
    mem.bumpN++;
    startBack(mem, d);
    if (mem.cur) mem.cur.bad += 0.5;
    mem.pos = [];
  }
  // stuck: barely moved in ~10 s
  if (mem.backT <= 0 && mem.avT <= 0 && !mem.gpsFrozen && mem.pos.length >= 101) {
    const p = mem.pos[0];
    if (dist(o.x, o.y, p.x, p.y) < 1.0) {
      mem.escN++;
      startBack(mem, d);
      if (mem.cur) mem.cur.bad += 1;
      mem.pos = [];
    }
  }
  if (mem.backT > 0) {
    mem.backT--;
    if (mem.backT === 0) mem.avT = 12;
    return mk(-0.3, -0.3);
  }
  if (mem.avT > 0) {
    mem.avT--;
    return mk(-0.3 * mem.avDir, 0.3 * mem.avDir);
  }
  // obstacle directly ahead while moving: pivot toward open side
  const front = Math.min(d[3], d[4], d[5]);
  if (fwd && front < 2.0 && dB > 4) {
    mem.avDir = openSide(d);
    mem.avT = 8;
    return mk(-0.25 * mem.avDir, 0.25 * mem.avDir);
  }

  // delivery triggers
  if (mem.mode !== 'deliver') {
    if (carried > 0) {
      const eta = dB / 0.35 + 90;
      const urgent = carried >= mem.cap || obs.timeLeft < eta || obs.battery < 0.25;
      const opp = (obs.t || 0) >= mem.noDelUntil &&
        ((carried >= 3 && dB < 60) || (carried >= 2 && dB < 30) || (carried >= 1 && dB < 12));
      if (urgent || opp) { mem.mode = 'deliver'; mem.purpose = 'deliver'; mem.dockT = 0; }
    } else if (obs.battery < 0.12 && obs.timeLeft > 150) {
      mem.mode = 'deliver'; mem.purpose = 'rest'; mem.dockT = 0;
    }
  }
  if (mem.mode === 'deliver') {
    if (mem.purpose === 'deliver' && carried === 0) {
      mem.mode = 'explore';
    } else if (mem.purpose === 'rest' && (obs.battery > 0.5 || obs.timeLeft < 60)) {
      mem.mode = 'explore';
    } else {
      return deliverStep(o, obs, mem, d);
    }
  }

  // nearby site: approach and drill
  const s = obs.site;
  if (s && carried < mem.cap) {
    const sw = siteWorld(o, mem, s);
    if (!findSkip(mem, sw.x, sw.y)) {
      if ((obs.t || 0) - mem.lastSiteT > 1.0) mem.siteT0 = obs.t || 0;
      mem.lastSiteT = obs.t || 0;
      if ((obs.t || 0) - mem.siteT0 <= 60) {
        return siteStep(o, obs, mem, d, s, sw);
      }
      addSkip(mem, sw.x, sw.y, 2);
    }
  }

  pushScience(o, obs, mem);

  if (!mem.cur || mem.cur.done) pickTarget(o, mem);
  const cur = mem.cur;
  if (!cur) return zero();

  if (cur.bad >= 3 || mem.ticks - cur.t0 > 2000) {
    cur.done = true; mem.cur = null;
    return zero();
  }
  if (!cur.arrived) {
    if (dist(o.x, o.y, cur.x, cur.y) < 4) {
      cur.arrived = true;
      cur.wps = lawnPts(o, cur);
      cur.wi = 0;
      cur.sT = mem.ticks;
    } else {
      return navTo(o, mem, cur.x, cur.y, CRUISE, d, 3.0) || zero();
    }
  }
  if (cur.wi >= cur.wps.length || mem.ticks - cur.sT > 900) {
    cur.done = true;
    markNear(mem, cur.x, cur.y, 10);
    mem.cur = null;
    return zero();
  }
  const w = cur.wps[cur.wi];
  if (dist(o.x, o.y, w.x, w.y) < 1.5) { cur.wi++; return zero(); }
  return navTo(o, mem, w.x, w.y, CRUISE, d, 1.0) || zero();
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.ticks++;

  // GPS freeze detection with dead reckoning from wheel speeds
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.frozen++;
  else { mem.frozen = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  mem.gpsFrozen = mem.frozen > 40 && mem.lastAvg > 0.15;
  if (mem.gpsFrozen) {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
    mem.px += v * 0.1 * Math.cos(mem.hd * D2R);
    mem.py += v * 0.1 * Math.sin(mem.hd * D2R);
  } else {
    mem.px = obs.x; mem.py = obs.y;
  }

  const o = Object.assign({}, obs, { x: mem.px, y: mem.py });
  mem.pos.push({ x: o.x, y: o.y });
  if (mem.pos.length > 101) mem.pos.shift();

  updateHeading(o, mem);
  const d = readRays(obs, mem);
  const cmd = decide(o, obs, mem, d);
  mem.lastL = cmd.left; mem.lastR = cmd.right;
  mem.lastAvg = (cmd.left + cmd.right) / 2;
  return { left: cmd.left, right: cmd.right, drill: !!cmd.drill };
}

function act(obs, mem) {
  try {
    return step(obs, mem);
  } catch (e) {
    return zero();
  }
}
